set -euo pipefail
task_root=/opt/market-mcp-deploy/mcp
test "$(realpath "$task_root")" = "$task_root"
python3 - <<'PY'
import ast,base64,hashlib,shutil,zlib
from datetime import datetime,timezone
from pathlib import Path
root=Path('/opt/market-mcp-deploy/mcp')
expected={'reputation_server.py':'0d08c64582770f2dcdbc28ecc32eb114a33c1172b08c363daf6d3282b0a4f19b','reputation_sources.py':'fb8980d1a8bed17e3c2d91ddd2a04f3a7ecf655df01a8e9414321db6fa2eea2b'}
packed={"reputation_server.py":"","reputation_sources.py":""}
payloads={}
for name,value in packed.items():
    path=root/'market_data'/name
    assert path.resolve().parent==root/'market_data'
    assert hashlib.sha256(path.read_bytes()).hexdigest()==expected[name],'Source changed; stop'
    payloads[name]=zlib.decompress(base64.b64decode(value))
    ast.parse(payloads[name])
backup=root/'deploy/backups'/('reputation-analysis-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
backup.mkdir(parents=True,exist_ok=False)
for name in payloads:
    shutil.copy2(root/'market_data'/name,backup/name)
    assert (backup/name).read_bytes()==(root/'market_data'/name).read_bytes()
for name,payload in payloads.items():
    (root/'market_data'/name).write_bytes(payload)
    print(name,hashlib.sha256(payload).hexdigest())
print('backup='+str(backup))
PY
cd "$task_root/deploy"
rollback_tag="market-reputation-analysis-rollback:$(date -u +%Y%m%dT%H%M%SZ)"
old_image=$(docker inspect --format '{{.Image}}' deploy-reputation-mcp-1)
docker image tag "$old_image" "$rollback_tag"
printf 'rollback_image=%s\n' "$rollback_tag"
docker compose build reputation-mcp
docker compose up -d --no-deps reputation-mcp
docker compose ps reputation-mcp
docker compose logs --tail=15 reputation-mcp

